public record PlanStep(int Id, string Description, string ExpectedOutcome, bool IsCompleted);
public record ExecutionPlan(string Goal, List<PlanStep> Steps);

public class PlanningAgent
{
    private readonly IChatClient _chatClient;
    private readonly IToolDispatcher _tools;

    public PlanningAgent(IChatClient chatClient, IToolDispatcher tools)
    {
        _chatClient = chatClient;
        _tools = tools;
    }

    public async Task<string> ExecuteWithPlanAsync(string objective, CancellationToken ct = default)
    {
        // Step 1: Generate initial plan
        var planPrompt = $"Create a minimal, strictly numbered step-by-step plan to achieve: '{objective}'.\n" +
                         $"Return pure JSON conforming to schema: {nameof(ExecutionPlan)}";

        var planResponse = await _chatClient.CompleteAsync(planPrompt, new ChatOptions
        {
            ResponseFormat = ChatResponseFormat.ForJsonSchema<ExecutionPlan>()
        }, ct);

        var plan = JsonSerializer.Deserialize<ExecutionPlan>(planResponse.Message.Text!)
            ?? throw new InvalidOperationException("Failed to generate plan.");

        var executionLog = new StringBuilder();

        // Step 2: Sequentially execute each plan step
        for (int i = 0; i < plan.Steps.Count; i++)
        {
            var step = plan.Steps[i];
            executionLog.AppendLine($"Executing Step {step.Id}: {step.Description}");

            // Execute step with tools
            var stepResult = await _tools.ExecuteStepAsync(step.Description, ct);
            executionLog.AppendLine($"Result: {stepResult}");

            // Step 3: Reflection & Replanning check
            var reflectionPrompt = $"Goal: '{objective}'\n" +
                                   $"Completed Steps:\n{executionLog}\n" +
                                   $"Did step {step.Id} succeed? If an unexpected obstacle occurred, " +
                                   $"should we replan remaining steps? Answer 'OK' or provide new remaining steps.";

            var reflection = await _chatClient.CompleteAsync(reflectionPrompt, cancellationToken: ct);
            if (reflection.Message.Text?.StartsWith("REPLAN:") == true)
            {
                // Dynamically update plan
                executionLog.AppendLine("Plan updated based on runtime observation.");
            }
        }

        // Step 4: Final synthesis
        return await _chatClient.CompleteAsync(
            $"Synthesize a final report for objective '{objective}' based on:\n{executionLog}", cancellationToken: ct)
            .ContinueWith(t => t.Result.Message.Text ?? string.Empty);
    }
}
